{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "일반 공원에 작은 텐트를 치고 쉬는 경우 벌금 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "일반 공원(도시공원)에서 텐트를 치고 쉬는 행위는 서울특별시 도시공원 조례 제22조제1항에 따라 금지되는 행위에 해당할 수 있어, 이를 위반하면 과태료 등 제재 대상이 될 수 있습니다. 다만 같은 조 제2항은 공원관리청이 공익에 부합한다고 판단해 허용한 행사의 경우 도시공원 관리에 현저한 지장을 주지 않는 범위에서 일부 행위를 허용할 수 있다고 정하고 있으므로, 그러한 허용 행사에 해당하지 않는 일반 개인의 텐트 설치는 허용되지 않습니다.",
          "b_ids": "도시공원:제22조제1항, 도시공원:제22조제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "한강에서 텐트를 친 사례와 일반 공원 텐트 허용 여부의 혼동",
      "c_basis": "SILENT",
      "d_claims": [],
      "e_status": "CORE_MISSING"
    }
  ]
}
